    ?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Connexion — École Pilot</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-body"><main class="login-card"><div class="brand-mark">EP</div><p class="eyebrow">Portail pédagogique</p><h1>Bienvenue</h1><p class="muted">Connectez-vous pour accéder à votre établissement.</p><?php if(isset($error)):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="_token" value="<?=csrf()?>"><label>Adresse e-mail<input type="email" name="email" required autofocus></label><label>Mot de passe<input type="password" name="password" required></label><button>Se connecter</button></form></main></body></html><?php exit;
