function rows(string $sql, array $params=[]): array { $s=db()->prepare($sql);$s->execute($params);return $s->fetchAll(); }
function one(string $sql, array $params=[]): ?array { $s=db()->prepare($sql);$s->execute($params);return $s->fetch() ?: null; }
function can_manage_class(int $classId): bool {
    if (user()['role']==='admin') return true;
    $s=db()->prepare('SELECT COUNT(*) FROM classes c LEFT JOIN courses co ON co.class_id=c.id LEFT JOIN course_teachers ct ON ct.course_id=co.id WHERE c.id=? AND (c.principal_user_id=? OR ct.user_id=?)');
    $s->execute([$classId,user()['id'],user()['id']]); return (int)$s->fetchColumn()>0;
}
function can_manage_course(int $courseId): bool {
    if (user()['role'] === 'admin') return true;
    $stmt = db()->prepare('SELECT COUNT(*) FROM courses co JOIN classes c ON c.id=co.class_id LEFT JOIN course_teachers ct ON ct.course_id=co.id WHERE co.id=? AND (ct.user_id=? OR c.principal_user_id=?)');
    $stmt->execute([$courseId, user()['id'], user()['id']]);
    return (int)$stmt->fetchColumn() > 0;
}
function normalized(array $grade): ?float {
    if ($grade['score'] === null || $grade['special_status']) return null;
    $target = $grade['normalize_to']==='10' ? 10 : 20;
    return ((float)$grade['score']/(float)$grade['scale'])*$target;
}
function nav_active(string $name): string { global $page; return $page===$name?'active':''; }

// Actions administratives
if ($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['action'])) {
    $action=$_POST['action'];
    if ($action==='save_settings') {
        require_role(['admin']);
        $stmt=$pdo->prepare('UPDATE settings SET school_name=?,school_address=?,grading_mode=?,decimals=? WHERE id=1');
        $stmt->execute([trim($_POST['school_name']),trim($_POST['school_address']),$_POST['grading_mode'],max(0,min(3,(int)$_POST['decimals']))]); audit('update','settings',1,null,$_POST); flash('Paramètres enregistrés.'); redirect('index.php?page=settings');
    }
    if ($action==='add_user') {
        require_role(['admin']); $stmt=$pdo->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');
        $stmt->execute([trim($_POST['name']),strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']]); audit('create','user',(int)$pdo->lastInsertId()); flash('Compte créé.'); redirect('index.php?page=users');
    }
    if ($action==='add_year') {
        require_role(['admin']); $pdo->prepare('UPDATE school_years SET active=0 WHERE ?=1')->execute([(int)($_POST['active']??0)]);
        $stmt=$pdo->prepare('INSERT INTO school_years(name,starts_on,ends_on,active) VALUES(?,?,?,?)');$stmt->execute([trim($_POST['name']),$_POST['starts_on'],$_POST['ends_on'],(int)($_POST['active']??0)]);audit('create','school_year',(int)$pdo->lastInsertId());flash('Année créée.');redirect('index.php?page=structure');
    }
    if ($action==='add_period') {
        require_role(['admin']);$stmt=$pdo->prepare('INSERT INTO periods(school_year_id,name,starts_on,ends_on,entry_opens_on,entry_closes_on,status,sort_order) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([(int)$_POST['school_year_id'],trim($_POST['name']),$_POST['starts_on'],$_POST['ends_on'],$_POST['entry_opens_on']?:null,$_POST['entry_closes_on']?:null,$_POST['status'],(int)$_POST['sort_order']]);audit('create','period',(int)$pdo->lastInsertId());flash('Période créée.');redirect('index.php?page=structure');
    }
    if ($action==='add_class') {
        require_role(['admin']);$stmt=$pdo->prepare('INSERT INTO classes(school_year_id,name,level,principal_user_id) VALUES(?,?,?,?)');$stmt->execute([(int)$_POST['school_year_id'],trim($_POST['name']),trim($_POST['level']),$_POST['principal_user_id']?:null]);audit('create','class',(int)$pdo->lastInsertId());flash('Classe créée.');redirect('index.php?page=structure');
    }
    if ($action==='add_subject') {
        require_role(['admin']);$stmt=$pdo->prepare('INSERT INTO subjects(name,coefficient) VALUES(?,?)');$stmt->execute([trim($_POST['name']),(float)$_POST['coefficient']]);audit('create','subject',(int)$pdo->lastInsertId());flash('Matière créée.');redirect('index.php?page=structure');
    }
    if ($action==='add_course') {
        require_role(['admin']);$stmt=$pdo->prepare('INSERT INTO courses(class_id,subject_id,group_name) VALUES(?,?,?)');$stmt->execute([(int)$_POST['class_id'],(int)$_POST['subject_id'],trim($_POST['group_name'])?:null]);audit('create','course',(int)$pdo->lastInsertId());flash('Cours créé.');redirect('index.php?page=structure');
    }
    if ($action==='assign_teacher') {
        require_role(['admin']);$stmt=$pdo->prepare('INSERT INTO course_teachers(course_id,user_id,assignment_role,can_edit_shared) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE assignment_role=VALUES(assignment_role),can_edit_shared=VALUES(can_edit_shared)');$stmt->execute([(int)$_POST['course_id'],(int)$_POST['user_id'],$_POST['assignment_role'],(int)($_POST['can_edit_shared']??0)]);audit('assign','course_teacher',(int)$_POST['course_id']);flash('Enseignant affecté.');redirect('index.php?page=structure');
    }
    if ($action==='add_student') {
        require_role(['admin']);$pdo->beginTransaction();try{$stmt=$pdo->prepare('INSERT INTO students(registration_number,last_name,first_name,birth_date) VALUES(?,?,?,?)');$stmt->execute([trim($_POST['registration_number']),strtoupper(trim($_POST['last_name'])),trim($_POST['first_name']),$_POST['birth_date']?:null]);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO enrollments(student_id,class_id) VALUES(?,?)')->execute([$id,(int)$_POST['class_id']]);$pdo->commit();audit('create','student',$id);flash('Élève inscrit.');}catch(Throwable $e){$pdo->rollBack();throw $e;}redirect('index.php?page=students');
    }
    if ($action==='add_assessment') {
        $course=one('SELECT co.*,p.status period_status FROM courses co JOIN periods p ON p.id=? WHERE co.id=?',[(int)$_POST['period_id'],(int)$_POST['course_id']]);if(!$course||!can_manage_course((int)$course['id'])){http_response_code(403);exit('Accès interdit');}if(in_array($course['period_status'],['closed','validated'],true)){flash('Cette période est clôturée.','error');redirect('index.php?page=grades');}
        $scale=$settings['grading_mode']==='forced_20'?20:(float)$_POST['scale'];$normalize=$settings['grading_mode']==='forced_20'?'20':$_POST['normalize_to'];
        $stmt=$pdo->prepare('INSERT INTO assessments(course_id,period_id,author_id,title,assessment_date,scale,normalize_to,coefficient) VALUES(?,?,?,?,?,?,?,?)');$stmt->execute([(int)$_POST['course_id'],(int)$_POST['period_id'],user()['id'],trim($_POST['title']),$_POST['assessment_date'],$scale,$normalize,(float)$_POST['coefficient']]);$id=(int)$pdo->lastInsertId();audit('create','assessment',$id);flash('Évaluation créée. Saisissez maintenant les notes.');redirect('index.php?page=gradebook&id='.$id);
    }
    if ($action==='save_grades') {
        $assessment=one('SELECT a.*,co.class_id,p.status period_status FROM assessments a JOIN courses co ON co.id=a.course_id JOIN periods p ON p.id=a.period_id WHERE a.id=?',[(int)$_POST['assessment_id']]);if(!$assessment||!can_manage_course((int)$assessment['course_id'])){http_response_code(403);exit('Accès interdit');}if(in_array($assessment['period_status'],['closed','validated'],true)&&user()['role']!=='admin'){flash('Période clôturée.','error');redirect('index.php?page=gradebook&id='.$assessment['id']);}
        $stmt=$pdo->prepare('INSERT INTO grades(assessment_id,student_id,score,special_status,updated_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),special_status=VALUES(special_status),updated_by=VALUES(updated_by)');
        foreach($_POST['students']??[] as $sid=>$entry){$status=$entry['status']?:null;$score=$status?null:($entry['score']===''?null:(float)$entry['score']);if($score!==null&&($score<0||$score>(float)$assessment['scale']))continue;$stmt->execute([$assessment['id'],(int)$sid,$score,$status,user()['id']]);}audit('bulk_update','grades',(int)$assessment['id']);flash('Notes enregistrées.');redirect('index.php?page=gradebook&id='.$assessment['id']);
    }
    if ($action==='save_council') {
        $classId=(int)$_POST['class_id'];if(!can_manage_class($classId)){http_response_code(403);exit('Accès interdit');}$existing=one('SELECT * FROM councils WHERE student_id=? AND class_id=? AND period_id=?',[(int)$_POST['student_id'],$classId,(int)$_POST['period_id']]);if($existing&&$existing['validated_at']&&user()['role']!=='admin'){flash('Ce bulletin est verrouillé.','error');redirect('index.php?page=council&class_id='.$classId.'&period_id='.(int)$_POST['period_id'].'&student_id='.(int)$_POST['student_id']);}
        $stmt=$pdo->prepare('INSERT INTO councils(student_id,class_id,period_id,general_comment,mention,decision_text) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE general_comment=VALUES(general_comment),mention=VALUES(mention),decision_text=VALUES(decision_text)');$stmt->execute([(int)$_POST['student_id'],$classId,(int)$_POST['period_id'],trim($_POST['general_comment']),trim($_POST['mention']),trim($_POST['decision_text'])]);audit('update','council',(int)($_POST['student_id']),$existing,$_POST);flash('Décision enregistrée.');redirect('index.php?page=council&class_id='.$classId.'&period_id='.(int)$_POST['period_id'].'&student_id='.(int)$_POST['student_id']);
    }
    if ($action==='validate_council') {
        require_role(['admin','principal']);$classId=(int)$_POST['class_id'];if(!can_manage_class($classId)){http_response_code(403);exit('Accès interdit');}$pdo->prepare('UPDATE councils SET validated_at=NOW(),validated_by=? WHERE student_id=? AND class_id=? AND period_id=?')->execute([user()['id'],(int)$_POST['student_id'],$classId,(int)$_POST['period_id']]);audit('validate','council',(int)$_POST['student_id']);flash('Bulletin validé et verrouillé.');redirect('index.php?page=bulletin&class_id='.$classId.'&period_id='.(int)$_POST['period_id'].'&student_id='.(int)$_POST['student_id']);
    }
}

