if($page==='structure'){require_role(['admin']);$years=rows('SELECT * FROM school_years ORDER BY starts_on DESC');$periods=rows('SELECT p.*,y.name year_name FROM periods p JOIN school_years y ON y.id=p.school_year_id ORDER BY y.starts_on DESC,p.sort_order');$principals=rows("SELECT id,name FROM users WHERE role IN ('principal','admin') AND active=1 ORDER BY name");$classes=rows('SELECT c.*,y.name year_name,u.name principal FROM classes c JOIN school_years y ON y.id=c.school_year_id LEFT JOIN users u ON u.id=c.principal_user_id ORDER BY y.starts_on DESC,c.name');$subjects=rows('SELECT * FROM subjects ORDER BY name');$courses=rows("SELECT co.id,co.group_name,c.name class_name,s.name subject,GROUP_CONCAT(CONCAT(u.name,' (',ct.assignment_role,')') SEPARATOR ', ') teachers FROM courses co JOIN classes c ON c.id=co.class_id JOIN subjects s ON s.id=co.subject_id LEFT JOIN course_teachers ct ON ct.course_id=co.id LEFT JOIN users u ON u.id=ct.user_id GROUP BY co.id ORDER BY c.name,s.name");$teachers=rows("SELECT id,name FROM users WHERE role IN ('teacher','principal','admin') AND active=1 ORDER BY name");header_html('Structure scolaire');?><div class="tabs"><button data-tab="years">Années & périodes</button><button data-tab="classes">Classes & matières</button><button data-tab="courses">Cours & enseignants</button></div><section class="tab-pane" id="years"><div class="two-col"><div class="panel"><h2>Années et périodes</h2><?php foreach($years as $y):?><h3><?=e($y['name'])?> <?=$y['active']?'<span class="tag">active</span>':''?></h3><?php foreach($periods as $p): if($p['school_year_id']===$y['id']):?><p class="list-row"><span><strong><?=e($p['name'])?></strong><small><?=date('d/m/Y',strtotime($p['starts_on']))?> → <?=date('d/m/Y',strtotime($p['ends_on']))?></small></span><span class="tag"><?=e($p['status'])?></span></p><?php endif; endforeach; endforeach?></div><div><form class="panel" method="post"><h2>Nouvelle année</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_year"><label>Libellé<input required name="name" placeholder="2026-2027"></label><div class="form-row"><label>Début<input required type="date" name="starts_on"></label><label>Fin<input required type="date" name="ends_on"></label></div><label class="check"><input type="checkbox" name="active" value="1"> Année active</label><button>Créer</button></form><form class="panel" method="post"><h2>Nouvelle période</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_period"><label>Année<select required name="school_year_id"><?php foreach($years as $y):?><option value="<?=$y['id']?>"><?=e($y['name'])?></option><?php endforeach?></select></label><label>Nom<input required name="name" placeholder="Trimestre 1"></label><div class="form-row"><label>Début<input required type="date" name="starts_on"></label><label>Fin<input required type="date" name="ends_on"></label></div><div class="form-row"><label>Ouverture saisie<input type="date" name="entry_opens_on"></label><label>Fermeture saisie<input type="date" name="entry_closes_on"></label></div><div class="form-row"><label>État<select name="status"><option value="draft">Préparation</option><option value="open">Ouverte</option><option value="closed">Clôturée</option></select></label><label>Ordre<input type="number" name="sort_order" min="1" value="1"></label></div><button>Créer</button></form></div></div></section><section class="tab-pane" id="classes"><div class="two-col"><div class="panel"><h2>Classes</h2><?php foreach($classes as $c):?><p class="list-row"><span><strong><?=e($c['name'])?></strong><small><?=e($c['level'])?> · <?=e($c['year_name'])?></small></span><span><?=e($c['principal']?:'Non affecté')?></span></p><?php endforeach?><h2>Matières</h2><?php foreach($subjects as $s):?><p class="list-row"><strong><?=e($s['name'])?></strong><span>coef. <?=e($s['coefficient'])?></span></p><?php endforeach?></div><div><form class="panel" method="post"><h2>Nouvelle classe</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_class"><label>Année<select name="school_year_id"><?php foreach($years as $y):?><option value="<?=$y['id']?>"><?=e($y['name'])?></option><?php endforeach?></select></label><label>Nom<input required name="name" placeholder="4e A"></label><label>Niveau<input name="level" placeholder="4e"></label><label>Professeur principal<select name="principal_user_id"><option value="">Non affecté</option><?php foreach($principals as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach?></select></label><button>Créer</button></form><form class="panel" method="post"><h2>Nouvelle matière</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_subject"><label>Nom<input required name="name"></label><label>Coefficient<input required type="number" min="0.1" step="0.1" name="coefficient" value="1"></label><button>Créer</button></form></div></div></section><section class="tab-pane" id="courses"><div class="two-col"><div class="panel"><h2>Cours et co-enseignement</h2><?php foreach($courses as $c):?><p class="list-row"><span><strong><?=e($c['subject'])?> · <?=e($c['class_name'])?></strong><small><?=e($c['group_name']?:'Classe entière')?></small></span><span><?=e($c['teachers']?:'Aucun enseignant')?></span></p><?php endforeach?></div><div><form class="panel" method="post"><h2>Nouveau cours</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_course"><label>Classe<select name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?> · <?=e($c['year_name'])?></option><?php endforeach?></select></label><label>Matière<select name="subject_id"><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach?></select></label><label>Groupe (facultatif)<input name="group_name"></label><button>Créer</button></form><form class="panel" method="post"><h2>Affecter un enseignant</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="assign_teacher"><label>Cours<select name="course_id"><?php foreach($courses as $c):?><option value="<?=$c['id']?>"><?=e($c['class_name'])?> · <?=e($c['subject'])?></option><?php endforeach?></select></label><label>Enseignant<select name="user_id"><?php foreach($teachers as $u):?><option value="<?=$u['id']?>"><?=e($u['name'])?></option><?php endforeach?></select></label><label>Rôle<select name="assignment_role"><option value="lead">Référent</option><option value="co_teacher">Co-enseignant</option><option value="substitute">Remplaçant</option><option value="contributor">Intervenant</option></select></label><label class="check"><input type="checkbox" name="can_edit_shared" value="1"> Peut modifier les évaluations partagées</label><button>Affecter</button></form></div></div></section><?php footer_html();exit;}

if($page==='students'){$classes=rows('SELECT c.id,c.name,y.name year_name FROM classes c JOIN school_years y ON y.id=c.school_year_id ORDER BY y.starts_on DESC,c.name');$students=rows('SELECT s.*,c.name class_name,y.name year_name FROM students s LEFT JOIN enrollments e ON e.student_id=s.id LEFT JOIN classes c ON c.id=e.class_id LEFT JOIN school_years y ON y.id=c.school_year_id ORDER BY s.last_name,s.first_name');header_html('Élèves');?><div class="<?=user()['role']==='admin'?'two-col':'one-col'?>"><section class="panel"><div class="panel-head"><div><p class="eyebrow">Répertoire</p><h2><?=count($students)?> élèves</h2></div><input class="search" type="search" placeholder="Rechercher…" data-filter-table></div><table data-table><thead><tr><th>Élève</th><th>Matricule</th><th>Classe</th><th>Année</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><strong><?=e($s['last_name'].' '.$s['first_name'])?></strong></td><td><?=e($s['registration_number'])?></td><td><?=e($s['class_name']?:'—')?></td><td><?=e($s['year_name']?:'—')?></td></tr><?php endforeach?></tbody></table></section><?php if(user()['role']==='admin'):?><form class="panel sticky" method="post"><h2>Inscrire un élève</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_student"><label>Matricule<input required name="registration_number"></label><div class="form-row"><label>Nom<input required name="last_name"></label><label>Prénom<input required name="first_name"></label></div><label>Date de naissance<input type="date" name="birth_date"></label><label>Classe<select required name="class_id"><?php foreach($classes as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?> · <?=e($c['year_name'])?></option><?php endforeach?></select></label><button>Inscrire</button></form><?php endif?></div><?php footer_html();exit;}

if($page==='grades'){$courseSql=user()['role']==='admin'?'':' WHERE c.principal_user_id=:uid OR ct.user_id=:uid';$courses=rows('SELECT DISTINCT co.id,CONCAT(c.name," · ",s.name,IF(co.group_name IS NULL,"",CONCAT(" · ",co.group_name))) label FROM courses co JOIN classes c ON c.id=co.class_id JOIN subjects s ON s.id=co.subject_id LEFT JOIN course_teachers ct ON ct.course_id=co.id'.$courseSql.' ORDER BY label',user()['role']==='admin'?[]:['uid'=>user()['id']]);$periods=rows("SELECT p.id,CONCAT(y.name,' · ',p.name) label,p.status FROM periods p JOIN school_years y ON y.id=p.school_year_id ORDER BY y.starts_on DESC,p.sort_order");$assessments=rows('SELECT a.*,s.name subject,c.name class_name,(SELECT COUNT(*) FROM grades g WHERE g.assessment_id=a.id) grade_count FROM assessments a JOIN courses co ON co.id=a.course_id JOIN subjects s ON s.id=co.subject_id JOIN classes c ON c.id=co.class_id ORDER BY a.assessment_date DESC');header_html('Notes et évaluations');?><div class="two-col"><section class="panel"><h2>Évaluations</h2><table><thead><tr><th>Titre</th><th>Classe</th><th>Barème</th><th>Saisies</th></tr></thead><tbody><?php foreach($assessments as $a):?><tr><td><a href="?page=gradebook&id=<?=$a['id']?>"><strong><?=e($a['title'])?></strong></a><small><?=e($a['subject'])?> · <?=date('d/m/Y',strtotime($a['assessment_date']))?></small></td><td><?=e($a['class_name'])?></td><td>/ <?=e($a['scale'])?></td><td><?=e($a['grade_count'])?></td></tr><?php endforeach?><?php if(!$assessments):?><tr><td colspan="4" class="empty">Aucune évaluation.</td></tr><?php endif?></tbody></table></section><form class="panel sticky" method="post"><h2>Créer une évaluation</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="add_assessment"><label>Cours<select required name="course_id"><?php foreach($courses as $c):?><option value="<?=$c['id']?>"><?=e($c['label'])?></option><?php endforeach?></select></label><label>Période<select required name="period_id"><?php foreach($periods as $p):?><option value="<?=$p['id']?>"><?=e($p['label'])?> · <?=e($p['status'])?></option><?php endforeach?></select></label><label>Titre du devoir<input required name="title" placeholder="Contrôle — fractions"></label><label>Date<input required type="date" name="assessment_date" value="<?=date('Y-m-d')?>"></label><?php if($settings['grading_mode']==='flexible'):?><div class="form-row"><label>Noté sur<input required type="number" min="0.01" step="0.01" name="scale" value="20"></label><label>Normaliser<select name="normalize_to"><option value="20">sur 20</option><option value="10">sur 10</option><option value="none">affichage original</option></select></label></div><?php else:?><div class="alert info">La saisie sur 20 est imposée par l’administration.</div><input type="hidden" name="scale" value="20"><input type="hidden" name="normalize_to" value="20"><?php endif?><label>Coefficient<input required type="number" min="0.1" step="0.1" name="coefficient" value="1"></label><button>Créer et saisir les notes</button></form></div><?php footer_html();exit;}

if($page==='gradebook'){$a=one('SELECT a.*,s.name subject,c.name class_name,co.class_id,p.name period_name,p.status period_status,u.name author FROM assessments a JOIN courses co ON co.id=a.course_id JOIN subjects s ON s.id=co.subject_id JOIN classes c ON c.id=co.class_id JOIN periods p ON p.id=a.period_id JOIN users u ON u.id=a.author_id WHERE a.id=?',[(int)($_GET['id']??0)]);if(!$a||!can_manage_course((int)$a['course_id'])){http_response_code(404);exit('Évaluation introuvable');}$students=rows('SELECT s.id,s.last_name,s.first_name,g.score,g.special_status FROM enrollments e JOIN students s ON s.id=e.student_id LEFT JOIN grades g ON g.student_id=s.id AND g.assessment_id=? WHERE e.class_id=? ORDER BY s.last_name,s.first_name',[$a['id'],$a['class_id']]);header_html($a['title']);?><section class="panel"><div class="panel-head"><div><p class="eyebrow"><?=e($a['class_name'])?> · <?=e($a['subject'])?> · <?=e($a['period_name'])?></p><h2>Saisie sur <?=e($a['scale'])?> · coefficient <?=e($a['coefficient'])?></h2></div><span class="tag"><?=e($a['period_status'])?></span></div><form method="post"><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="save_grades"><input type="hidden" name="assessment_id" value="<?=$a['id']?>"><table class="grade-table"><thead><tr><th>Élève</th><th>Note / <?=e($a['scale'])?></th><th>Statut particulier</th><th>Équivalent</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><strong><?=e($s['last_name'].' '.$s['first_name'])?></strong></td><td><input aria-label="Note de <?=e($s['first_name'])?>" type="number" min="0" max="<?=e($a['scale'])?>" step="0.01" name="students[<?=$s['id']?>][score]" value="<?=e($s['score'])?>"></td><td><select name="students[<?=$s['id']?>][status]"><option value="">Noté</option><?php foreach(['absent'=>'Absent','excused'=>'Dispensé','missing'=>'Non rendu','not_graded'=>'Non noté'] as $k=>$v):?><option value="<?=$k?>" <?=$s['special_status']===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></td><td class="normalized" data-scale="<?=e($a['scale'])?>" data-target="<?=e($a['normalize_to'])?>">—</td></tr><?php endforeach?></tbody></table><div class="actions"><a class="button secondary" href="?page=grades">Retour</a><button <?=in_array($a['period_status'],['closed','validated'],true)&&user()['role']!=='admin'?'disabled':''?>>Enregistrer les notes</button></div></form></section><?php footer_html();exit;}

if($page==='council'){$classes=rows('SELECT DISTINCT c.id,c.name FROM classes c LEFT JOIN courses co ON co.class_id=c.id LEFT JOIN course_teachers ct ON ct.course_id=co.id WHERE ?="admin" OR c.principal_user_id=? OR ct.user_id=? ORDER BY c.name',[user()['role'],user()['id'],user()['id']]);$periods=rows('SELECT p.id,CONCAT(y.name," · ",p.name) label FROM periods p JOIN school_years y ON y.id=p.school_year_id ORDER BY y.starts_on DESC,p.sort_order');$classId=(int)($_GET['class_id']??($classes[0]['id']??0));$periodId=(int)($_GET['period_id']??($periods[0]['id']??0));$students=$classId?rows('SELECT s.id,s.last_name,s.first_name FROM enrollments e JOIN students s ON s.id=e.student_id WHERE e.class_id=? ORDER BY s.last_name,s.first_name',[$classId]):[];$studentId=(int)($_GET['student_id']??($students[0]['id']??0));$student=$studentId?one('SELECT * FROM students WHERE id=?',[$studentId]):null;$summary=$student?rows("SELECT s.name subject,GROUP_CONCAT(DISTINCT u.name ORDER BY u.name SEPARATOR ', ') teachers,ROUND(SUM((g.score/a.scale*20)*a.coefficient)/NULLIF(SUM(a.coefficient),0),2) average,MAX(sc.comment) comment FROM courses co JOIN subjects s ON s.id=co.subject_id LEFT JOIN course_teachers ct ON ct.course_id=co.id LEFT JOIN users u ON u.id=ct.user_id LEFT JOIN assessments a ON a.course_id=co.id AND a.period_id=? LEFT JOIN grades g ON g.assessment_id=a.id AND g.student_id=? AND g.special_status IS NULL LEFT JOIN subject_comments sc ON sc.course_id=co.id AND sc.period_id=? AND sc.student_id=? WHERE co.class_id=? GROUP BY co.id,s.name",[$periodId,$studentId,$periodId,$studentId,$classId]):[];$council=$student?one('SELECT * FROM councils WHERE student_id=? AND class_id=? AND period_id=?',[$studentId,$classId,$periodId]):null;$averages=array_values(array_filter(array_column($summary,'average'),fn($v)=>$v!==null));$overall=$averages?array_sum($averages)/count($averages):null;header_html('Conseil de classe');?><section class="council-toolbar"><form method="get"><input type="hidden" name="page" value="council"><select name="class_id" onchange="this.form.submit()"><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select><select name="period_id" onchange="this.form.submit()"><?php foreach($periods as $p):?><option value="<?=$p['id']?>" <?=$periodId===$p['id']?'selected':''?>><?=e($p['label'])?></option><?php endforeach?></select><select name="student_id" onchange="this.form.submit()"><?php foreach($students as $s):?><option value="<?=$s['id']?>" <?=$studentId===$s['id']?'selected':''?>><?=e($s['last_name'].' '.$s['first_name'])?></option><?php endforeach?></select></form><button class="secondary" data-projector>Mode vidéoprojecteur</button><button class="ghost" data-privacy>Masquer les données</button></section><?php if($student):?><section class="student-spotlight"><div><p class="eyebrow">Élève examiné</p><h2><?=e($student['first_name'].' '.$student['last_name'])?></h2><span><?=e($student['registration_number'])?></span></div><div class="overall"><small>Moyenne générale</small><strong><?=$overall!==null?number_format($overall,(int)$settings['decimals'],',',' '):'—'?></strong><span>/ 20</span></div></section><div class="council-grid"><section class="panel"><table><thead><tr><th>Matière</th><th>Enseignant(s)</th><th>Moyenne</th><th>Appréciation</th></tr></thead><tbody><?php foreach($summary as $s):?><tr><td><strong><?=e($s['subject'])?></strong></td><td><?=e($s['teachers']?:'—')?></td><td class="score"><?=$s['average']!==null?number_format((float)$s['average'],(int)$settings['decimals'],',',' '):'—'?></td><td><?=e($s['comment']?:'Non renseignée')?></td></tr><?php endforeach?></tbody></table></section><form class="panel decision" method="post"><h2>Synthèse du conseil</h2><input type="hidden" name="_token" value="<?=csrf()?>"><input type="hidden" name="action" value="save_council"><input type="hidden" name="student_id" value="<?=$studentId?>"><input type="hidden" name="class_id" value="<?=$classId?>"><input type="hidden" name="period_id" value="<?=$periodId?>"><label>Appréciation générale<textarea name="general_comment" rows="6"><?=e($council['general_comment']??'')?></textarea></label><label>Mention<select name="mention"><option value="">Aucune</option><?php foreach(['Encouragements','Compliments','Félicitations','Avertissement travail','Avertissement comportement'] as $m):?><option <?=$m===($council['mention']??'')?'selected':''?>><?=e($m)?></option><?php endforeach?></select></label><label>Décision<input name="decision_text" value="<?=e($council['decision_text']??'')?>" placeholder="Passage, orientation…"></label><button <?=!empty($council['validated_at'])&&user()['role']!=='admin'?'disabled':''?>>Enregistrer en séance</button><?php if(empty($council['validated_at'])):?><button class="success-button" name="action" value="validate_council">Valider et verrouiller</button><?php else:?><div class="alert success">Validé le <?=date('d/m/Y à H:i',strtotime($council['validated_at']))?></div><a class="button secondary" href="?page=bulletin&class_id=<?=$classId?>&period_id=<?=$periodId?>&student_id=<?=$studentId?>">Voir le bulletin</a><?php endif?></form></div><?php else:?><div class="empty-state"><h2>Préparez votre premier conseil</h2><p>Créez une classe, une période et inscrivez des élèves.</p></div><?php endif?><?php footer_html();exit;}

if(in_array($page,['bulletin','report'],true)){$studentId=(int)($_GET['student_id']??0);$classId=(int)($_GET['class_id']??0);$periodId=(int)($_GET['period_id']??0);if(!can_manage_class($classId)){http_response_code(403);exit('Accès interdit');}$student=one('SELECT s.*,c.name class_name,y.name year_name FROM students s JOIN enrollments e ON e.student_id=s.id JOIN classes c ON c.id=e.class_id JOIN school_years y ON y.id=c.school_year_id WHERE s.id=? AND c.id=?',[$studentId,$classId]);$period=one('SELECT * FROM periods WHERE id=?',[$periodId]);$summary=rows("SELECT s.name subject,GROUP_CONCAT(DISTINCT u.name ORDER BY u.name SEPARATOR ', ') teachers,ROUND(SUM((g.score/a.scale*20)*a.coefficient)/NULLIF(SUM(a.coefficient),0),2) average,MAX(sc.comment) comment FROM courses co JOIN subjects s ON s.id=co.subject_id LEFT JOIN course_teachers ct ON ct.course_id=co.id LEFT JOIN users u ON u.id=ct.user_id LEFT JOIN assessments a ON a.course_id=co.id AND a.period_id=? LEFT JOIN grades g ON g.assessment_id=a.id AND g.student_id=? AND g.special_status IS NULL LEFT JOIN subject_comments sc ON sc.course_id=co.id AND sc.period_id=? AND sc.student_id=? WHERE co.class_id=? GROUP BY co.id,s.name",[$periodId,$studentId,$periodId,$studentId,$classId]);$details=rows('SELECT a.title,a.assessment_date,s.name subject,a.scale,a.normalize_to,a.coefficient,g.score,g.special_status FROM assessments a JOIN courses co ON co.id=a.course_id JOIN subjects s ON s.id=co.subject_id LEFT JOIN grades g ON g.assessment_id=a.id AND g.student_id=? WHERE co.class_id=? AND a.period_id=? ORDER BY s.name,a.assessment_date',[$studentId,$classId,$periodId]);$council=one('SELECT * FROM councils WHERE student_id=? AND class_id=? AND period_id=?',[$studentId,$classId,$periodId]);$averages=array_values(array_filter(array_column($summary,'average'),fn($v)=>$v!==null));$overall=$averages?array_sum($averages)/count($averages):null;?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title><?=e($page==='bulletin'?'Bulletin':'Relevé')?> — <?=e($student['last_name'])?></title><link rel="stylesheet" href="assets/app.css"></head><body class="document-body"><div class="print-actions"><a class="button secondary" href="javascript:history.back()">Retour</a><button onclick="window.print()">Enregistrer au format PDF / Imprimer</button></div><article class="school-document"><header><div><p class="eyebrow"><?=e($settings['school_name'])?></p><p><?=nl2br(e($settings['school_address']))?></p></div><div class="doc-title"><h1><?=$page==='bulletin'?'Bulletin scolaire':'Relevé de notes'?></h1><p><?=e($period['name'])?> · <?=e($student['year_name'])?></p></div></header><section class="identity"><div><small>Élève</small><strong><?=e($student['first_name'].' '.$student['last_name'])?></strong><span>Matricule <?=e($student['registration_number'])?></span></div><div><small>Classe</small><strong><?=e($student['class_name'])?></strong></div><div><small>Moyenne générale</small><strong><?=$overall!==null?number_format($overall,(int)$settings['decimals'],',',' ').' / 20':'Non calculable'?></strong></div></section><?php if($page==='bulletin'):?><table><thead><tr><th>Matière</th><th>Enseignant(s)</th><th>Moyenne</th><th>Appréciation</th></tr></thead><tbody><?php foreach($summary as $s):?><tr><td><?=e($s['subject'])?></td><td><?=e($s['teachers'])?></td><td class="score"><?=$s['average']!==null?number_format((float)$s['average'],(int)$settings['decimals'],',',' ').' / 20':'—'?></td><td><?=e($s['comment'])?></td></tr><?php endforeach?></tbody></table><section class="final-comment"><h2>Appréciation générale</h2><p><?=e($council['general_comment']??'Non renseignée')?></p><div class="mention"><strong><?=e($council['mention']??'')?></strong><span><?=e($council['decision_text']??'')?></span></div></section><?php else:?><table><thead><tr><th>Matière</th><th>Évaluation</th><th>Date</th><th>Note</th><th>Coef.</th></tr></thead><tbody><?php foreach($details as $d):?><tr><td><?=e($d['subject'])?></td><td><?=e($d['title'])?></td><td><?=date('d/m/Y',strtotime($d['assessment_date']))?></td><td><?=$d['special_status']?e($d['special_status']):($d['score']!==null?e($d['score'].' / '.$d['scale']):'—')?></td><td><?=e($d['coefficient'])?></td></tr><?php endforeach?></tbody></table><?php endif?><footer>Document édité le <?=date('d/m/Y à H:i')?> · <?=e($settings['school_name'])?></footer></article></body></html><?php exit;}

http_response_code(404); echo 'Page introuvable';
